"""Freeze a five-by-five natural alpha transition bank; no snapshot restore."""
import argparse,itertools,json,subprocess
from pathlib import Path
p=argparse.ArgumentParser();p.add_argument('--source',type=Path,required=True);p.add_argument('--output',type=Path,required=True);a=p.parse_args();r=a.output;r.mkdir(parents=True,exist_ok=False)
alphas=[0,.25,.5,.75,1];pairs=list(itertools.product(alphas,repeat=2));labels=[f'{x:g}_to_{y:g}' for x,y in pairs]+['Zero_from_start','fixed05_duplicate','fixed1_duplicate'];prefix=[x for x,y in pairs]+[0,.5,1];targets=[y for x,y in pairs]+[0,.5,1];spec=json.loads((a.source/'protocol.json').read_text());spec.update(experiment_id='H75_STATE_ALPHA_SCAN',title='入障前状态与五档alpha配对：5×5自然切换',prefix_alphas=alphas,target_alphas=alphas,case_labels=labels,execution_modes=['independent']*28,lanes=336,max_physics_lane_steps=16800000,batch_cases=12,max_batch_envs=4096,compact_results=True,retain_physics_contacts=False,configured_lanes=True,data_role='Familiar-layout DEV; physical-group-held-out selector diagnostic',interpretation='25 natural prefix/target schedules plus Zero and two duplicates; common original start; switch at original route progress2.5m; no restore',duplicate_pairs=[['0.5_to_0.5','fixed05_duplicate'],['1_to_1','fixed1_duplicate']],code_revision=subprocess.check_output(['git','rev-parse','HEAD'],text=True).strip(),selector_protocol=dict(features='normalized latest measured roll, IMUx, steering angle/rate, speed, path error, heading sin/cos, correction offsets/filters, requested speed; all from before switch',rule='3 nearest states in same terrain family, excluding the entire held-out physical group; rank mean task pass then normalized path/speed cost with failure penalty10 then smaller alpha',roles='DEV only; not held-out terrain TEST',stop='one finite bank; no parameter search or training',paired_initial_tolerance='Report maximum XY/measurement pre-switch spread; only exact common switch tick and spreads <=1mm / .001 measurement units enter same-entry selector diagnostic; all episodes retained in overall results'))
jobs=[]
for old in json.loads((a.source/'jobs.json').read_text()):
 cfg=json.loads(Path(old['config']).read_text());cfg.update(num_envs=28,trace_lanes=28,alphas=prefix,zero_middle=[False]*25+[True,False,False],case_labels=labels,compact_results=True)
 cfg['alpha_switch'].update(target_alpha=targets,execution_modes=['independent']*28)
 cfg['plant_options'].update(track_wheel_contacts=False,track_contact_wrench=False,raw_contact_only=False)
 cfg.pop('physics_contact_recording',None)
 dest=r/(old['name']+'.json');dest.write_text(json.dumps(cfg,indent=2));jobs.append(dict(old,config=str(dest)))
(r/'protocol.json').write_text(json.dumps(spec,indent=2,ensure_ascii=False));(r/'jobs.json').write_text(json.dumps(jobs,indent=2));(r/'status.json').write_text(json.dumps(dict(stage='prepared',planned=12,episodes=336)))
(r/'README.md').write_text('# 五档状态相关选档验证\n\n12工况 × (25自然切换＋Zero＋2重复)=336条；每条10s、0训练。冻结协议见protocol.json。\n\n先保留全部XY、每步/累计奖励、失败原因和轨迹；随后留一物理组检查状态选档。三个物理组均为已用DEV，不称新布局泛化。只在共同前段与切换时刻核对成立的组上作同入口选档分析；缺失或前段失败保留并单列。\n\n路径：RESULTS.md（全覆盖XY）、ANALYSIS.md（完整任务与终止）、state_selection.md（选档诊断）、status.json。此处是执行计划，不是实验结果。\n')
print(r)
